class Color {
  constructor(r, g, b) {
    this.values = [r, g, b];
    this.getRed = function () {
      return this.values[0];
    };
  }
}

// -----------------------------------------

console.log(new Color().getRed === new Color().getRed); // false

class Color {
  constructor(r, g, b) {
    this.values = [r, g, b];
